class RingQueue {
  private buf: number[];
  private head = 0;
  private count = 0;

  constructor(private k: number) {
    this.buf = new Array(k).fill(0);
  }

  enqueue(value: number): boolean {
    if (this.count === this.k) return false;
    this.buf[(this.head + this.count) % this.k] = value;
    this.count++;
    return true;
  }
  dequeue(): boolean {
    if (this.count === 0) return false;
    this.head = (this.head + 1) % this.k;
    this.count--;
    return true;
  }
  front(): number { return this.count ? this.buf[this.head] : -1; }
  rear(): number { return this.count ? this.buf[(this.head + this.count - 1) % this.k] : -1; }
  isEmpty(): boolean { return this.count === 0; }
  isFull(): boolean { return this.count === this.k; }
}

